    const FLM_LOCAL_OIL_COMPANY_GROUPS = [
        ['flax', 8], ['sunflower', 8], ['corn', 8], ['peanut', 8],
        ['rapeseed', 10], ['soybean', 8], ['blend', 8], ['olive', 10]
    ];
