        rapeseed: { label: '福临门菜籽油', words: ['菜籽'] },
        blend: { label: '福临门调和油', words: ['调和'] },
        flax: { label: '福临门亚麻籽油或胡麻油', words: ['亚麻', '胡麻'] },
